  /// Owner opt-in/opt-out and approve public-safe catalog metadata
  ///
  /// Managed course only, owner required, expectedRevision CAS, default unlisted, private README never extracted. Unlisting must invalidate cached catalog responses or TTL<=60s.
  Future<models.DeferredJson> updateCourseCatalog(
    models.UpdateCourseCatalogRequest body, {
    Map<String, Object?> extra = const {
      "openapi.servers": [
        {"url": "/api"},
      ],
      "openapi.security": [
        {"WebSession": []},
        {"FirebaseBearer": []},
      ],
      "openapi.securitySchemes": {
        "WebSession": {
          "type": "apiKey",
          "name": "__Host-course_session",
          "in": "cookie",
        },
        "FirebaseBearer": {
          "type": "http",
          "scheme": "bearer",
          "bearerFormat": "FirebaseIDToken",
        },
      },
    },
    CancelToken? cancelToken,
    Options? options,
    required models.ManifestId courseId,

    /// Replay the same mutation with the same key within 24 hours to receive its first result (E7, V4-SEC-09).
    required String idempotencyKey,
  }) async {
    if (const {
      '',
      '.',
      '..',
    }.contains(Uri.encodeComponent((courseId.toJson()).toString()))) {
      throw ArgumentError('Invalid path segment.');
    }
    final _options = (options ?? Options()).copyWith(
      method: "PUT",
      responseType: ResponseType.json,
      extra: {...?options?.extra, ...extra},
      contentType: "application/json",
      headers: {
        for (final entry
            in (options?.headers ?? const <String, Object?>{}).entries)
          if (entry.key.toLowerCase() != 'content-type') entry.key: entry.value,
        'Accept': "application/json",
        "Idempotency-Key": idempotencyKey,
      },
      validateStatus: (status) => status != null && (status == 200),
    );
    final response = await _transport.request<dynamic>(
      "/courses/" +
          Uri.encodeComponent((courseId.toJson()).toString()) +
          "/catalog",
      options: _options,
      data: convert.jsonEncode(body),
      cancelToken: cancelToken,
    );
    return models.DeferredJson.fromJson(response.data);
  }

